<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Hearth — Mortgage Planner UI Concept</title>
<style>
:root{--ink:#152a35;--muted:#69808c;--bg:#f5f8f9;--line:#dce7e9;--teal:#137b79;--dark:#0c343c;--tint:#e9f6f3;--blue:#6e8fcd;--orange:#eab776;--panel:#fff;--shadow:0 14px 42px rgba(18,50,58,.055)}
*{box-sizing:border-box}
body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--bg);color:var(--ink);font-size:14px}
button,input,select{font:inherit}
button{cursor:pointer}
button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #79c5b7;outline-offset:2px}
.top{background:#fff;border-bottom:1px solid var(--line)}
.nav{max-width:1440px;margin:auto;padding:16px 35px;display:flex;align-items:center;justify-content:space-between;gap:18px}
.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--dark);font-size:21px;font-weight:800;letter-spacing:-.9px}
.brandmark{width:36px;height:36px;border-radius:11px;background:#0f746f;color:white;display:grid;place-items:center;font-size:21px}
.navlinks{display:flex;gap:28px}
.navlinks a{color:#637985;text-decoration:none;font-weight:600;font-size:13px}
.navlinks a.active{color:var(--teal)}
.ghost{background:#fff;border:1px solid var(--line);border-radius:10px;padding:10px 16px;font-weight:700;color:var(--ink)}
.shell{max-width:1440px;margin:auto;padding:35px 35px 70px}
.eyebrow{font-size:11px;color:var(--teal);font-weight:800;letter-spacing:1.8px;text-transform:uppercase}
.intro{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:24px}
.intro h1{margin:8px 0;font-size:clamp(28px,3vw,39px);letter-spacing:-1.5px;font-weight:760}
.intro p{margin:0;color:var(--muted);font-size:14px;line-height:1.5}
.intro .hint{font-size:12px;color:#56717b;background:#eaf0f2;border:1px solid #d8e5e8;border-radius:30px;padding:9px 12px;white-space:nowrap}
.layout{display:grid;grid-template-columns:minmax(350px, .9fr) minmax(440px,1.25fr);gap:23px;align-items:start}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow)}
.pad{padding:27px}
.panel-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:22px}
.panel-head h2{font-size:17px;letter-spacing:-.35px;margin:0}
.caption{font-size:12px;color:var(--muted)}
.fields{display:grid;grid-template-columns:1fr 1fr;gap:17px}
.full{grid-column:1/-1}
label{display:block;font-weight:700;font-size:12px;margin-bottom:8px}
.field{position:relative}
.field input,.field select{width:100%;height:47px;border-radius:10px;border:1px solid #d5e2e5;background:#fff;color:var(--ink);font-weight:660;padding:0 12px}
.field input.with-prefix{padding-left:29px}
.field input.with-suffix{padding-right:31px}
.affix{position:absolute;left:13px;top:15px;color:var(--muted);font-size:13px;font-weight:650}
.affix.right{left:auto;right:13px}
.seg{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;background:#edf3f4;padding:4px;border-radius:11px}
.seg button{border:0;background:transparent;border-radius:8px;padding:10px 8px;font-weight:700;color:#617983}
.seg button.active{background:white;box-shadow:0 2px 7px #183b4212;color:var(--teal)}
.mode{display:flex;gap:7px;margin-bottom:9px}
.mode button{border:0;background:none;font-size:11px;color:var(--muted);font-weight:700;padding:0}
.mode button.active{color:var(--teal);text-decoration:underline;text-underline-offset:3px}
.divider{height:1px;background:var(--line);margin:23px 0}
.options details{border-top:1px solid var(--line);padding:17px 0}
.options summary{list-style:none;display:flex;align-items:center;justify-content:space-between;cursor:pointer;font-size:13px;font-weight:750}
.options summary::-webkit-details-marker{display:none}
.options summary:after{content:'+';font-size:20px;color:var(--teal);font-weight:400}
.options details[open] summary:after{content:'−'}
.options .fields{padding-top:19px}
.sub{font-size:11px;color:var(--muted);margin-top:6px;line-height:1.5}
.primary{background:var(--teal);border:0;color:white;padding:13px 18px;border-radius:10px;font-weight:800}
.row{display:flex;justify-content:space-between;gap:12px;align-items:center}
.result{background:linear-gradient(130deg,#0a4148,#0d5c5a);padding:29px;border-radius:18px;color:white;box-shadow:var(--shadow)}
.result .eyebrow{color:#9ed4ce}
.resulthead{display:flex;justify-content:space-between;gap:12px;align-items:start}
.pill{background:#ffffff22;color:#dbf4ef;border-radius:25px;padding:7px 10px;font-size:11px;font-weight:700}
.big{font-size:clamp(38px,4.2vw,57px);font-weight:800;letter-spacing:-2px;margin:9px 0 4px;font-variant-numeric:tabular-nums}
.big small{font-size:14px;font-weight:500;color:#b2d8d5;letter-spacing:0}
.result p{color:#b9d7d7;font-size:12px;margin:0}
.whitecard{background:white;border-radius:14px;color:var(--ink);padding:17px 19px;margin-top:24px}
.break{display:flex;align-items:center;gap:21px}
.donut{width:136px;aspect-ratio:1;border-radius:50%;background:conic-gradient(var(--teal) 0 70%,var(--blue) 70% 93%,var(--orange) 93% 98%,#c4d4d6 98%);display:grid;place-items:center;flex-shrink:0}
.donut:before{content:'';background:white;border-radius:50%;width:92px;height:92px;grid-area:1/1}
.donut-inner{grid-area:1/1;position:relative;text-align:center;font-weight:800;font-size:17px}
.donut-inner small{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:1px;font-weight:700}
.legend{flex:1;min-width:0}
.legendrow{display:flex;align-items:center;justify-content:space-between;gap:9px;padding:7px 0;border-bottom:1px solid #edf1f2;font-size:12px}
.legendrow:last-child{border:0}
.legendrow strong{font-size:12px;font-variant-numeric:tabular-nums}
.dot{width:8px;height:8px;border-radius:50%;display:inline-block;margin-right:7px}
.section-title{font-size:16px;margin:0 0 17px;letter-spacing:-.3px}
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.stat{border:1px solid var(--line);background:white;border-radius:14px;padding:18px 17px}
.stat strong{display:block;font-size:21px;margin-top:9px;letter-spacing:-.6px;font-variant-numeric:tabular-nums}
.stat small{color:var(--muted);font-size:11px}
.below{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:23px}
.plotbox{height:190px;position:relative;overflow:hidden}
.plotbox svg{width:100%;height:100%}
.switch{display:flex;align-items:center;gap:6px;background:#edf3f4;padding:4px;border-radius:8px}
.switch button{padding:8px 11px;border:0;border-radius:6px;background:transparent;font-size:12px;font-weight:700;color:#647986}
.switch button.active{background:white;color:var(--teal);box-shadow:0 1px 4px #1234}
.tablewrap{overflow:auto;max-height:230px}
table{width:100%;border-collapse:collapse;font-size:12px;white-space:nowrap}
th{background:#f4f8f9;color:#72858e;font-weight:700;text-align:right;padding:12px;position:sticky;top:0}
th:first-child,td:first-child{text-align:left}
td{padding:12px;border-bottom:1px solid #edf2f3;text-align:right;font-variant-numeric:tabular-nums}
.warning{margin-top:22px;border:1px solid #d8e8e7;background:#edf7f5;color:#506d73;border-radius:12px;padding:14px 17px;line-height:1.6;font-size:12px}
.flag{color:#aad6cd;font-size:12px}
.mini{color:var(--muted);font-size:12px}
.mobile-nav{display:none}
.tooltip{border-bottom:1px dotted #98afaf;cursor:help}
.mutedbtn{background:transparent;border:1px solid #dbe7e8;color:var(--teal);border-radius:9px;padding:8px 12px;font-weight:750;font-size:12px}
.mobile-summary{display:none}
@media(max-width:1000px){.layout{grid-template-columns:1fr}
.below{grid-template-columns:1fr}
.intro .hint{display:none}
.result{position:static}
.navlinks{display:none}
.mobile-nav{display:block;color:var(--muted)}
}
@media(min-width:1001px){.sticky{position:sticky;top:20px}
}
@media(max-width:620px){.nav{padding:13px 17px}
.shell{padding:24px 15px 90px}
.intro h1{font-size:29px}
.pad,.result{padding:20px}
.fields{gap:13px}
.break{flex-direction:column;align-items:stretch}
.donut{margin:auto}
.stats{grid-template-columns:1fr 1fr}
.stat:last-child{grid-column:1/-1}
.big{font-size:43px}
.mobile-summary{display:flex;position:fixed;bottom:0;left:0;right:0;background:white;box-shadow:0 -8px 28px #1232;padding:12px 17px;z-index:4;align-items:center;justify-content:space-between;gap:12px}
.mobile-summary strong{font-size:22px}
.nav .ghost{display:none}
}
@media(prefers-reduced-motion:no-preference){.panel,.stat{transition:box-shadow .2s}
}
@media print{.top,.options,.mobile-summary,.ghost,.primary{display:none!important}
body{background:white}
.shell{padding:0}
.layout,.below{display:block}
.panel{box-shadow:none;break-inside:avoid}
.result{print-color-adjust:exact}
}

</style>
</head>
