/**
 * Owns the calculator input state. Typing updates `state` immediately; the
 * loan derivation reads a deferred copy so a slow recalculation never blocks
 * keystrokes (INP). `today` is injectable so tests can fix the stale check.
 */
export const useCalculatorInputs = (today?: Date) => {
	const [state, dispatch] = useReducer(
		calculatorReducer,
		initialCalculatorState,
	);
	const deferredInputs = useDeferredValue(state.inputs);
	const derived = useMemo(() => deriveLoan(deferredInputs), [deferredInputs]);
	const arm = useMemo(
		() => deriveArm(deferredInputs, derived.loan),
		[deferredInputs, derived.loan],
	);
	// An invalid ARM input shows an error and no result at all.
	const loan =
		deferredInputs.loanType === "arm" && Object.keys(arm.errors).length > 0
			? null
			: derived.loan;
	const propertyTax = useMemo(
		() => derivePropertyTax(deferredInputs),
		[deferredInputs],
	);
	const closing = useMemo(
		() => deriveClosingCosts(deferredInputs, loan),
		[deferredInputs, loan],
	);
	const monthlyCosts = useMemo(
		() => deriveMonthlyCosts(deferredInputs),
		[deferredInputs],
	);
	const schedule = useMemo(() => {
		if (!loan) return null;
		if (deferredInputs.loanType === "arm") return arm.result?.rows ?? null;
		return buildSchedule({
			loan: loan.loanAmount,
			rate: loan.interestRate,
			payments: loan.termYears * 12,
		});
	}, [loan, deferredInputs.loanType, arm.result]);
	const extra = useMemo(
		() => deriveExtraPayments(deferredInputs, loan, schedule),
		[deferredInputs, loan, schedule],
	);
	const pmi = useMemo(
		() => derivePmi(deferredInputs, loan, schedule, extra.result?.rows ?? null),
		[deferredInputs, loan, schedule, extra.result],
	);
	const estimate = useMemo(
		() =>
			buildMonthlyEstimate(
				loan,
				propertyTax.tax,
				monthlyCosts.costs,
				pmi.result,
			),
		[loan, propertyTax.tax, monthlyCosts.costs, pmi.result],
	);
	// Its errors stay out of the shared error set: a blank income must not
	// hide the payment estimate.
	const affordability = useMemo(
		() => deriveAffordability(deferredInputs, estimate),
		[deferredInputs, estimate],
	);
	const now = useMemo(() => today ?? new Date(), [today]);
	const assumptions = useMemo(
		() =>
			buildAssumptions({
				inputs: deferredInputs,
				loan,
				tax: propertyTax.tax,
				costs: monthlyCosts.costs,
				pmi: pmi.result,
				affordability: affordability.result,
				today: now,
			}),
		[
			deferredInputs,
			loan,
			propertyTax.tax,
			monthlyCosts.costs,
			pmi.result,
			affordability.result,
			now,
		],
	);
	const current = useMemo<ResultSet>(
		() => ({
			loan,
			arm: arm.result,
			tax: propertyTax.tax,
			costs: monthlyCosts.costs,
			pmi: pmi.result,
			estimate,
			closing: closing.costs,
			affordability: affordability.result,
			schedule,
			extra: extra.result,
			assumptions,
		}),
		[
			loan,
			arm.result,
			propertyTax.tax,
			monthlyCosts.costs,
			pmi.result,
			estimate,
			closing.costs,
			affordability.result,
			schedule,
			extra.result,
			assumptions,
		],
	);

	// Non-numeric text in a money field keeps the last valid result on screen;
	// every other error clears it (PRD S-10).
	const errors = {
		...derived.errors,
		...propertyTax.errors,
		...monthlyCosts.errors,
		...arm.errors,
		...pmi.errors,
		...closing.errors,
	};
	const isComplete =
		estimate !== null &&
		Object.values(errors).every((message) => message === undefined);
	const lastValid = useRef<ResultSet | null>(null);
	useEffect(() => {
		if (isComplete) lastValid.current = current;
	}, [isComplete, current]);
	const held = keepsLastResult(errors, deferredInputs)
		? lastValid.current
		: null;

	return {
		state,
		dispatch,
		derived,
		arm,
		propertyTax,
		monthlyCosts,
		pmi,
		closing,
		affordability,
		extra,
		results: held ?? current,
		showingLastResult: held !== null,
	};
};
import Disclaimer from "@/components/feedback/Disclaimer";
import { formatMoney } from "@/lib/money";
import { formatRate } from "@/lib/rate";
import type { ArmSummary } from "../armSchedule";
import type { EstimateLine, MonthlyEstimate } from "../monthlyEstimate";

interface MonthlyEstimateCardProps {
	estimate: MonthlyEstimate | null;
	/** Set for a valid 5/6 ARM: the estimate shows the first-period payment. */
	arm?: ArmSummary | null;
	/** An illustrative default behind this estimate is past the stale limit. */
	outOfDate?: boolean;
}

const Lines = ({
	lines,
	piLabel,
}: {
	lines: readonly EstimateLine[];
	piLabel?: string | undefined;
}) => (
	<>
		{lines.map((line) => (
			<div key={line.id} className="flex justify-between gap-4 py-1">
				<dt className="text-slate-700">
					{line.id === "pi" && piLabel ? piLabel : line.label}
				</dt>
				<dd className="font-medium text-slate-900">
					{formatMoney(line.amount)}
				</dd>
			</div>
		))}
	</>
);

const ResetRisk = ({ arm }: { arm: ArmSummary }) => (
	<div className="mt-4 rounded-md bg-amber-50 p-3 text-sm text-amber-950 ring-1 ring-amber-400">
		<p className="font-semibold">
			Reset risk: this payment is for months 1 to 60
		</p>
		{arm.rises ? (
			<p className="mt-1">
				After month 60 the rate resets every 6 months. With the{" "}
				{arm.presetLabel.toLowerCase()} index path, principal and interest
				reaches {formatMoney(arm.peakPayment)} a month by month {arm.peakMonth}{" "}
				(rate up to {formatRate(arm.peakRate)}).{" "}
				<span className="whitespace-nowrap rounded bg-amber-100 px-1.5 py-0.5 text-xs font-medium ring-1 ring-amber-400">
					Hypothetical rate
				</span>
			</p>
		) : (
			<p className="mt-1">
				After month 60 the rate resets every 6 months. With the{" "}
				{arm.presetLabel.toLowerCase()} index path, principal and interest does
				not go above {formatMoney(arm.firstPayment)}, but a different index
				could raise it.{" "}
				<span className="whitespace-nowrap rounded bg-amber-100 px-1.5 py-0.5 text-xs font-medium ring-1 ring-amber-400">
					Hypothetical rate
				</span>
			</p>
		)}
	</div>
);

const MonthlyEstimateCard = ({
	estimate,
	arm,
	outOfDate = false,
}: MonthlyEstimateCardProps) => (
	<section
		aria-labelledby="monthly-estimate-heading"
		className="rounded-lg bg-brand-50 p-4 sm:p-6 ring-1 ring-brand-500/30"
	>
		<h2
			id="monthly-estimate-heading"
			className="text-sm font-medium text-slate-700"
		>
			Estimated monthly cost
		</h2>
		<div aria-live="polite">
			{estimate ? (
				<>
					<p className="mt-1 text-4xl font-bold tracking-tight text-slate-900">
						{formatMoney(estimate.total)}
						<span className="ml-1 text-base font-normal text-slate-600">
							/ month total
						</span>
					</p>
					<div className="mt-4 grid gap-5 border-t border-slate-300/60 pt-4 text-sm sm:grid-cols-2">
						<div>
							<h3 className="font-semibold text-slate-800">
								Lender payment (escrow)
							</h3>
							<dl className="mt-1">
								<Lines
									lines={estimate.lender}
									piLabel={
										arm ? "Principal and interest (months 1–60)" : undefined
									}
								/>
								<div className="mt-1 flex justify-between gap-4 border-t border-slate-300 pt-2">
									<dt className="font-semibold text-slate-800">
										Lender payment
									</dt>
									<dd className="font-semibold text-slate-900">
										{formatMoney(estimate.lenderPayment)}
									</dd>
								</div>
							</dl>
						</div>
						<div>
							<h3 className="font-semibold text-slate-800">Non-escrow</h3>
							<dl className="mt-1">
								<Lines lines={estimate.nonEscrow} />
								<div className="mt-1 flex justify-between gap-4 border-t border-slate-300 pt-2">
									<dt className="font-semibold text-slate-800">
										Non-escrow total
									</dt>
									<dd className="font-semibold text-slate-900">
										{formatMoney(estimate.nonEscrowTotal)}
									</dd>
								</div>
							</dl>
						</div>
					</div>
					{arm ? <ResetRisk arm={arm} /> : null}
					{outOfDate ? (
						<p className="mt-4 text-sm text-amber-950">
							<span className="rounded bg-amber-100 px-1.5 py-0.5 text-xs font-medium ring-1 ring-amber-400">
								May be out of date
							</span>{" "}
							Some illustrative defaults behind this estimate are over a year
							old. See the assumptions below.
						</p>
					) : null}
				</>
			) : (
				<p className="mt-1 text-base text-slate-700">
					Fix the highlighted fields to see the itemized monthly estimate.
				</p>
			)}
		</div>
		<div className="mt-4">
			<Disclaimer />
		</div>
	</section>
);

export default MonthlyEstimateCard;
import { useId } from "react";
import { cn } from "@/lib/cn";

interface TextFieldProps {
	label: string;
	value: string;
	onChange: (value: string) => void;
	onBlur: () => void;
	error?: string | undefined;
	hint?: string;
	prefix?: string;
	suffix?: string;
	readOnly?: boolean;
	className?: string;
}

const TextField = ({
	label,
	value,
	onChange,
	onBlur,
	error,
	hint,
	prefix,
	suffix,
	readOnly = false,
	className,
}: TextFieldProps) => {
	const id = useId();
	const errorId = `${id}-error`;
	const hintId = `${id}-hint`;
	const describedBy =
		[error ? errorId : null, hint ? hintId : null].filter(Boolean).join(" ") ||
		undefined;

	return (
		<div className={className}>
			<label htmlFor={id} className="block text-sm font-medium text-slate-800">
				{label}
			</label>
			<div
				className={cn(
					"mt-1 flex min-h-11 items-center rounded-md bg-white ring-1 ring-slate-300 focus-within:ring-2 focus-within:ring-brand-500",
					error && "ring-2 ring-red-600 focus-within:ring-red-600",
					readOnly && "bg-slate-100 text-slate-600",
				)}
			>
				{prefix ? (
					<span aria-hidden="true" className="pl-3 text-slate-500">
						{prefix}
					</span>
				) : null}
				<input
					id={id}
					type="text"
					inputMode="decimal"
					autoComplete="off"
					value={value}
					readOnly={readOnly}
					aria-readonly={readOnly || undefined}
					aria-invalid={error ? true : undefined}
					aria-describedby={describedBy}
					onChange={(event) => onChange(event.target.value)}
					onBlur={onBlur}
					className="w-full min-w-0 bg-transparent px-3 py-2 text-base outline-none"
				/>
				{suffix ? (
					<span aria-hidden="true" className="pr-3 text-slate-500">
						{suffix}
					</span>
				) : null}
			</div>
			{hint ? (
				<p id={hintId} className="mt-1 text-xs text-slate-500">
					{hint}
				</p>
			) : null}
			{error ? (
				<p
					id={errorId}
					role="alert"
					className="mt-1 text-sm font-medium text-red-700"
				>
					<span aria-hidden="true">⚠ </span>
					{error}
				</p>
			) : null}
		</div>
	);
};

export default TextField;

