import { type ReactNode, useEffect, useState } from "react";

interface CollapsibleProps {
	title: string;
	/** One line under the title saying what is inside. */
	caption?: string;
	defaultOpen?: boolean;
	/** A field inside has an error: open the section and flag it. */
	invalid?: boolean;
	children: ReactNode;
