/** A native <details> disclosure for a group of optional fields. */
const Collapsible = ({
	title,
	caption,
	defaultOpen = false,
	invalid = false,
	children,
}: CollapsibleProps) => {
	const [open, setOpen] = useState(defaultOpen);
	// An error in a closed section would be invisible, so open it.
	useEffect(() => {
